using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace ParkingLotEnvironment.CloudPilot {public static class ContextAudit {
 public static void Run(){try{EditorSceneManager.OpenScene("Assets/_Parkside/Scenes/ParklingLot.unity");var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");var s=new StringBuilder();foreach(Transform group in root.transform){var rr=group.GetComponentsInChildren<Renderer>();if(rr.Length>0){var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);s.AppendLine("ROOT "+group.name+" "+b+" active="+group.gameObject.activeSelf);}}
  foreach(var group in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="AG_Photorealistic3D_Assets"||t.name=="DaylightPass_Context"))foreach(Transform bld in group){var rr=bld.GetComponentsInChildren<Renderer>();if(rr.Length==0)continue;var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);s.AppendLine("BUILDING "+group.name+"/"+bld.name+" position="+bld.position+" euler="+bld.eulerAngles+" scale="+bld.lossyScale+" "+b+" renderers="+rr.Length);}
  var cam=root.GetComponentInChildren<Camera>();s.AppendLine("CAM "+cam.transform.position+" fov="+cam.fieldOfView+" HDR="+cam.allowHDR+" AA="+cam.allowMSAA);var truck=root.transform.Find("DaylightPass_Context/Daylight_ProvisionalTruck");foreach(var r in truck.GetComponentsInChildren<Renderer>(true))s.AppendLine("TRUCK "+r.name+" "+r.bounds+" materials="+string.Join("|",r.sharedMaterials.Select(m=>m.name+":"+m.shader.name)));
  File.WriteAllText("/workspaces/parkside-setup/context-audit-20261105.txt",s.ToString());EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
